#include <iostream>

// 返回 index 是否落在有效下标范围内。
bool is_valid_index(int index, int length) {
    return index >= 0 && index < length;
}

int main() {
    // 输入：2。输出：可以读取。
    int index = 0;
    if (!(std::cin >> index)) {
        std::cerr << "请输入整数。\n";
        return 1;
    }

    bool valid = is_valid_index(index, 4);
    if (valid) {
        std::cout << "可以读取。\n";
    } else {
        std::cout << "下标无效。\n";
    }
    return 0;
}
